// 1. Register Action in JS
EUIXEngineCore.registerAction("TRACK_EVENT", (actionNode, context) => {
  const evtName = actionNode.getAttribute("name");
  analytics.track(evtName, { timestamp: Date.now() });
});

// 2. Invoke Declaratively in XML:
// <on_click action="TRACK_EVENT" name="button_clicked" />

import { EUIXEngineCore } from 'euixjs/core';
import { EUIXRouterPlugin } from 'euixjs/router';
import { EUIXChartPlugin } from 'euixjs/chart';

EUIXEngineCore
  .use(EUIXRouterPlugin)
  .use(EUIXChartPlugin);

const engine = EUIXEngineCore.mount(xmlString, '#app');
